import requests

url='https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/tran_sf_railsu?time=2014&time=2020'
js=requests.get(url).json()
ids=js['id']; dims=js['dimension']; size=js['size']; values=js['value']
geo_pos=dims['geo']['category']['index']; time_pos=dims['time']['category']['index']
# multipliers
multipliers=[]; m=1
for s in reversed(size):
    multipliers.insert(0,m); m*=s

def get_val(geo,time):
    positions=[]
    for dim in ids:
        if dim=='geo': positions.append(geo_pos[geo])
        elif dim=='time': positions.append(time_pos[time])
        else: positions.append(0)
    idx=sum(p*mul for p,mul in zip(positions,multipliers))
    return values.get(str(idx))

countries={'Germany':'DE','Belgium':'BE','Portugal':'PT','Spain':'ES','UK':'UK','France':'FR','Croatia':'HR','Bulgaria':'BG'}
res=[]
for name,code in countries.items():
    a=get_val(code,'2014'); b=get_val(code,'2020')
    dec=(a-b)/a*100
    if dec < 45: res.append(name)
print(res)
